import{_ as d,C as s,o as e,c as o,a2 as a,b as c,w as l,a as i,E,a3 as r}from"./chunks/framework.RycU2wFZ.js";const u=JSON.parse('{"title":"防悬挂三态状态机规范","description":"","frontmatter":{},"headers":[],"relativePath":"protocol/state-machine.md","filePath":"protocol/state-machine.md"}'),p={name:"protocol/state-machine.md"};function A(g,t,h,B,f,x){const n=s("Mermaid");return e(),o("div",null,[t[1]||(t[1]=a(`<h1 id="防悬挂三态状态机规范" tabindex="-1">防悬挂三态状态机规范 <a class="header-anchor" href="#防悬挂三态状态机规范" aria-label="Permalink to &quot;防悬挂三态状态机规范&quot;">​</a></h1><blockquote><p><strong>版本</strong>：v2.0.0 (企业级生产规范)<br><strong>状态</strong>：<strong>已定稿 (Approved Specification)</strong><br><strong>核心定位</strong>：<strong>企业级 AI 行为审计与资金防火墙网关 (AI Agent Gateway &amp; FinOps)</strong><br><strong>适用范围</strong>：AgentPay Go Gateway 数据面、控制面、虚拟账本引擎与离线对账调度器</p></blockquote><hr><h2 id="_1-核心设计原则" tabindex="-1">1. 核心设计原则 <a class="header-anchor" href="#_1-核心设计原则" aria-label="Permalink to &quot;1. 核心设计原则&quot;">​</a></h2><p>在企业高并发与大语言模型流式调用中，网络超时、上游模型不可用是常态。若将业务意图、资金扣减与上游网络请求耦合在同一生命周期中，极易导致“请求超时但资金扣减”或“接口已返回但未记录扣费”等严重事故。</p><p>为此，AgentFinOps 严格执行<strong>三条状态线正交解耦（Orthogonal Decoupling）</strong>：</p><ol><li><strong>三条状态线严格正交分离</strong>： <ul><li><strong>支付意图（PaymentIntent）</strong>：业务层端到端请求生命周期（<code>created</code> $\\to$ <code>challenged</code> $\\to$ <code>authorized</code> $\\to$ <code>completed</code>）；</li><li><strong>结算状态（Settlement）</strong>：企业内部只追加虚拟账本的原子资金状态（<code>not_started</code> $\\to$ <code>held</code> $\\to$ <code>captured</code> $\\to$ <code>released</code>）；</li><li><strong>履约状态（Fulfillment）</strong>：下游模型与商业 API 接口的真实网络响应状态（<code>not_started</code> $\\to$ <code>in_progress</code> $\\to$ <code>succeeded</code> $\\to$ <code>failed</code>）。</li></ul></li><li><strong>两阶段防悬挂原子锁定（Hold $\\to$ Capture $\\to$ Release）</strong>： <ul><li>转发上游前，必须在数据库事务中完成预估最大金额的 <code>Hold</code> 冻结；</li><li>上游成功返回且流式响应结束，按真实 Token 消耗确扣 <code>Capture</code>，并原子 <code>Release</code> 剩余差额；</li><li>若上游发生超时或 4xx/5xx 错误，100% 自动 <code>Release</code>，绝无资金悬挂。</li></ul></li><li><strong>人在回路 (HITL) 挂起兼容</strong>： <ul><li>超过阈值请求转入 <code>needs_review</code> / <code>challenged</code>，签发 <code>approval_id</code> 后返回 402，允许异步审批放行后重放。</li></ul></li></ol><hr><h2 id="_2-三维状态正交矩阵" tabindex="-1">2. 三维状态正交矩阵 <a class="header-anchor" href="#_2-三维状态正交矩阵" aria-label="Permalink to &quot;2. 三维状态正交矩阵&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                        支付意图 (PaymentIntent)                        │</span></span>
<span class="line"><span>│   • created: 请求初次到达网关                                          │</span></span>
<span class="line"><span>│   • challenged: 已签发 402 Challenge (包含 approval_id 或配额挑战)    │</span></span>
<span class="line"><span>│   • authorized: 客户端携带合法凭证重试通过                             │</span></span>
<span class="line"><span>│   • completed: 扣费确权且上游履约成功 (终态)                           │</span></span>
<span class="line"><span>│   • rejected: 策略引擎阻断 / 超额被人工拒绝 (终态)                     │</span></span>
<span class="line"><span>│   • failed: 配额不足 / 系统级错误 (终态)                               │</span></span>
<span class="line"><span>│   • needs_review: 上游未知异常或挂起等待审批                           │</span></span>
<span class="line"><span>└───────────────────────────────────┬────────────────────────────────────┘</span></span>
<span class="line"><span>                                    │ 驱动与正交关联</span></span>
<span class="line"><span>                                    ▼</span></span>
<span class="line"><span>┌───────────────────────────────────┴────────────────────────────────────┐</span></span>
<span class="line"><span>│                        结算状态 (Settlement)                           │</span></span>
<span class="line"><span>│   • not_started: 尚未申请资金预留                                      │</span></span>
<span class="line"><span>│   • held: 预估最大金额已在虚拟账本中成功锁定 (Hold)                    │</span></span>
<span class="line"><span>│   • captured: 实际消耗金额已确认入账，写入不可变流水 (Capture)         │</span></span>
<span class="line"><span>│   • released: 预留额度已全额释放回可用余额池 (Release)                 │</span></span>
<span class="line"><span>│   • unknown: 扣费状态异常，需由日终平账器排查                          │</span></span>
<span class="line"><span>└───────────────────────────────────┬────────────────────────────────────┘</span></span>
<span class="line"><span>                                    │ 决定是否发起上游调用</span></span>
<span class="line"><span>                                    ▼</span></span>
<span class="line"><span>┌───────────────────────────────────┴────────────────────────────────────┐</span></span>
<span class="line"><span>│                        履约状态 (Fulfillment)                          │</span></span>
<span class="line"><span>│   • not_started: 尚未向下游商业模型或 API 发出网络调用                 │</span></span>
<span class="line"><span>│   • in_progress: 请求已转发，流式连接持续中                            │</span></span>
<span class="line"><span>│   • succeeded: 上游正常返回 HTTP 200 并传输完毕                        │</span></span>
<span class="line"><span>│   • failed: 上游返回 HTTP 4xx/5xx 或连接重置                           │</span></span>
<span class="line"><span>│   • unknown: 网关读取上游响应超时 (504 Timeout)                        │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="_3-核心流转时序与异常恢复" tabindex="-1">3. 核心流转时序与异常恢复 <a class="header-anchor" href="#_3-核心流转时序与异常恢复" aria-label="Permalink to &quot;3. 核心流转时序与异常恢复&quot;">​</a></h2>`,12)),(e(),c(r,null,{default:l(()=>[E(n,{id:"mermaid-85",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20actor%20Client%20as%20AI%20Agent%20(Client%20SDK)%0A%20%20%20%20participant%20GW%20as%20Go%20Gateway%0A%20%20%20%20participant%20Ledger%20as%20%E8%99%9A%E6%8B%9F%E8%B4%A6%E6%9C%AC%20(PostgreSQL)%0A%20%20%20%20participant%20Upstream%20as%20%E4%B8%8A%E6%B8%B8%E5%A4%A7%E6%A8%A1%E5%9E%8B%20%2F%20%E5%95%86%E4%B8%9A%20API%0A%0A%20%20%20%20Client-%3E%3EGW%3A%201.%20POST%20%2Fv1%2Fchat%2Fcompletions%20(%E5%B8%A6%20API%20Key)%0A%20%20%20%20GW-%3E%3EGW%3A%202.%20%E7%AD%96%E7%95%A5%E5%BC%95%E6%93%8E%E9%A2%84%E6%A3%80%20%26%20%E8%B7%AF%E7%94%B1%E6%A0%87%E4%BB%B7%E8%AE%A1%E7%AE%97%0A%20%20%20%20alt%20%E8%AF%B7%E6%B1%82%E9%9C%80%E8%A6%81%E5%AE%A1%E6%89%B9%20(HITL)%0A%20%20%20%20%20%20%20%20GW--%3E%3EClient%3A%203a.%20402%20APPROVAL_REQUIRED%20(%E6%90%BA%E5%B8%A6%20approval_id)%0A%20%20%20%20%20%20%20%20Note%20over%20Client%3A%20SDK%20%E6%8C%82%E8%B5%B7%E5%B9%B6%E7%AD%89%E5%BE%85%E5%AE%A1%E6%89%B9%E6%94%BE%E8%A1%8C...%0A%20%20%20%20else%20%E7%AD%96%E7%95%A5%E7%9B%B4%E6%8E%A5%E6%94%BE%E8%A1%8C%20(%E5%85%8D%E5%AE%A1%E9%A2%9D%E5%BA%A6)%0A%20%20%20%20%20%20%20%20GW-%3E%3ELedger%3A%203b.%20BEGIN%20TRANSACTION%3A%20%E6%89%A7%E8%A1%8C%20Hold%20(%E9%94%81%E5%AE%9A%E9%A2%84%E4%BC%B0%E9%87%91%E9%A2%9D%20Delta)%0A%20%20%20%20%20%20%20%20Ledger--%3E%3EGW%3A%20Hold%20%E6%88%90%E5%8A%9F%20(status%3Dheld)%0A%20%20%20%20%20%20%20%20GW-%3E%3EUpstream%3A%204.%20%E8%BD%AC%E5%8F%91%E8%AF%B7%E6%B1%82%E8%87%B3%E4%B8%8A%E6%B8%B8%E6%A8%A1%E5%9E%8B%E6%9C%8D%E5%8A%A1%0A%20%20%20%20%20%20%20%20%0A%20%20%20%20%20%20%20%20alt%20%E4%B8%8A%E6%B8%B8%E6%88%90%E5%8A%9F%E5%93%8D%E5%BA%94%20(HTTP%20200)%0A%20%20%20%20%20%20%20%20%20%20%20%20Upstream--%3E%3EGW%3A%205a.%20%E6%B5%81%E5%BC%8F%E4%BC%A0%E8%BE%93%E5%AE%8C%E6%88%90%20(%E5%AE%9E%E9%99%85%E6%B6%88%E8%80%97%20ActualCost)%0A%20%20%20%20%20%20%20%20%20%20%20%20GW-%3E%3ELedger%3A%206a.%20%E7%A1%AE%E6%89%A3%20Capture(ActualCost)%20%2B%20%E9%87%8A%E6%94%BE%20Release(Delta%20-%20ActualCost)%0A%20%20%20%20%20%20%20%20%20%20%20%20Ledger--%3E%3EGW%3A%20%E4%BA%8B%E5%8A%A1%E6%8F%90%E4%BA%A4%E6%88%90%E5%8A%9F%0A%20%20%20%20%20%20%20%20%20%20%20%20GW--%3E%3EClient%3A%207a.%20200%20OK%20(%E6%A8%A1%E5%9E%8B%E7%BB%93%E6%9E%9C%20%2B%20%E6%89%A3%E8%B4%B9%E6%98%8E%E7%BB%86)%0A%20%20%20%20%20%20%20%20else%20%E4%B8%8A%E6%B8%B8%E6%98%8E%E7%A1%AE%E6%8A%A5%E9%94%99%20(HTTP%204xx%2F5xx)%0A%20%20%20%20%20%20%20%20%20%20%20%20Upstream--%3E%3EGW%3A%205b.%20%E4%B8%8A%E6%B8%B8%E9%94%99%E8%AF%AF%E5%93%8D%E5%BA%94%0A%20%20%20%20%20%20%20%20%20%20%20%20GW-%3E%3ELedger%3A%206b.%20100%25%20%E5%85%A8%E9%A2%9D%E9%87%8A%E6%94%BE%20Release(Delta)%0A%20%20%20%20%20%20%20%20%20%20%20%20Ledger--%3E%3EGW%3A%20%E9%A2%9D%E5%BA%A6%E5%8E%9F%E8%B7%AF%E9%80%80%E5%9B%9E%E5%8F%AF%E7%94%A8%E6%B1%A0%0A%20%20%20%20%20%20%20%20%20%20%20%20GW--%3E%3EClient%3A%207b.%20%E8%BF%94%E5%9B%9E%E5%AF%B9%E5%BA%94%E9%94%99%E8%AF%AF%E7%A0%81%20(%E9%9B%B6%E6%89%A3%E8%B4%B9)%0A%20%20%20%20%20%20%20%20else%20%E4%B8%8A%E6%B8%B8%E8%B6%85%E6%97%B6%E6%9C%AA%E5%93%8D%E5%BA%94%20(504%20Timeout)%0A%20%20%20%20%20%20%20%20%20%20%20%20Upstream--xGW%3A%205c.%20%E8%B6%85%E6%97%B6%E4%B8%AD%E6%96%AD%0A%20%20%20%20%20%20%20%20%20%20%20%20GW-%3E%3EGW%3A%20%E6%A0%87%E8%AE%B0%E6%84%8F%E5%9B%BE%E4%B8%BA%20needs_review%0A%20%20%20%20%20%20%20%20%20%20%20%20GW-%3E%3ELedger%3A%206c.%20%E5%8E%9F%E5%AD%90%E8%A7%A6%E5%8F%91%20Release(Delta)%20%E4%BF%9D%E6%8A%A4%E4%BC%81%E4%B8%9A%E8%B5%84%E4%BA%A7%0A%20%20%20%20%20%20%20%20%20%20%20%20GW--%3E%3EClient%3A%207c.%20504%20Gateway%20Timeout%20(%E9%9B%B6%E6%89%A3%E8%B4%B9)%0A%20%20%20%20%20%20%20%20end%0A%20%20%20%20end%0A"})]),fallback:l(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<hr><h2 id="_4-状态转移矩阵与约束表" tabindex="-1">4. 状态转移矩阵与约束表 <a class="header-anchor" href="#_4-状态转移矩阵与约束表" aria-label="Permalink to &quot;4. 状态转移矩阵与约束表&quot;">​</a></h2><h3 id="_4-1-支付意图转移表-paymentintent" tabindex="-1">4.1 支付意图转移表 (<code>PaymentIntent</code>) <a class="header-anchor" href="#_4-1-支付意图转移表-paymentintent" aria-label="Permalink to &quot;4.1 支付意图转移表 (`PaymentIntent`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">当前状态</th><th style="text-align:left;">触发事件</th><th style="text-align:left;">目标状态</th><th style="text-align:left;">约束条件</th></tr></thead><tbody><tr><td style="text-align:left;"><code>created</code></td><td style="text-align:left;"><code>policy_passed</code></td><td style="text-align:left;"><code>authorized</code></td><td style="text-align:left;">免审额度，策略评估直接放行</td></tr><tr><td style="text-align:left;"><code>created</code></td><td style="text-align:left;"><code>approval_triggered</code></td><td style="text-align:left;"><code>challenged</code></td><td style="text-align:left;">超过风控阈值，签发 402 挂起</td></tr><tr><td style="text-align:left;"><code>challenged</code></td><td style="text-align:left;"><code>approval_granted</code></td><td style="text-align:left;"><code>authorized</code></td><td style="text-align:left;">负责人移动端点击批准</td></tr><tr><td style="text-align:left;"><code>challenged</code></td><td style="text-align:left;"><code>approval_rejected</code></td><td style="text-align:left;"><code>rejected</code></td><td style="text-align:left;">负责人点击拒绝或审批单超时</td></tr><tr><td style="text-align:left;"><code>authorized</code></td><td style="text-align:left;"><code>settlement_captured</code></td><td style="text-align:left;"><code>completed</code></td><td style="text-align:left;">账本确扣成功且上游履约成功</td></tr><tr><td style="text-align:left;"><code>authorized</code></td><td style="text-align:left;"><code>settlement_failed</code></td><td style="text-align:left;"><code>failed</code></td><td style="text-align:left;">可用余额不足，冻结失败</td></tr></tbody></table><h3 id="_4-2-结算状态转移表-settlement" tabindex="-1">4.2 结算状态转移表 (<code>Settlement</code>) <a class="header-anchor" href="#_4-2-结算状态转移表-settlement" aria-label="Permalink to &quot;4.2 结算状态转移表 (`Settlement`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">当前状态</th><th style="text-align:left;">触发事件</th><th style="text-align:left;">目标状态</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>not_started</code></td><td style="text-align:left;"><code>hold_reserve</code></td><td style="text-align:left;"><code>held</code></td><td style="text-align:left;">数据库行级排他锁锁定预估额度</td></tr><tr><td style="text-align:left;"><code>not_started</code></td><td style="text-align:left;"><code>hold_insufficient</code></td><td style="text-align:left;"><code>failed</code></td><td style="text-align:left;">钱包余额不足，拒绝透支</td></tr><tr><td style="text-align:left;"><code>held</code></td><td style="text-align:left;"><code>capture_success</code></td><td style="text-align:left;"><code>captured</code></td><td style="text-align:left;">按真实消耗扣除，写入账本底账</td></tr><tr><td style="text-align:left;"><code>held</code></td><td style="text-align:left;"><code>release_success</code></td><td style="text-align:left;"><code>released</code></td><td style="text-align:left;">调用失败或超时，原子全额解冻</td></tr><tr><td style="text-align:left;"><code>held</code></td><td style="text-align:left;"><code>system_panic</code></td><td style="text-align:left;"><code>unknown</code></td><td style="text-align:left;">异常掉电或崩溃，交由离线对账巡检</td></tr></tbody></table><hr><h2 id="_5-组合状态与运维处置矩阵" tabindex="-1">5. 组合状态与运维处置矩阵 <a class="header-anchor" href="#_5-组合状态与运维处置矩阵" aria-label="Permalink to &quot;5. 组合状态与运维处置矩阵&quot;">​</a></h2><p>控制台根据 <code>(PaymentIntent, Settlement, Fulfillment)</code> 三元组计算面向财务与运维人员的派生状态：</p><table tabindex="0"><thead><tr><th style="text-align:left;">结算状态</th><th style="text-align:left;">履约状态</th><th style="text-align:left;">运维宏观状态</th><th style="text-align:left;">业务语义与系统动作</th></tr></thead><tbody><tr><td style="text-align:left;"><code>held</code></td><td style="text-align:left;"><code>in_progress</code></td><td style="text-align:left;"><code>PROCESSING</code></td><td style="text-align:left;">请求正在上游执行，额度已安全冻结中</td></tr><tr><td style="text-align:left;"><code>captured</code></td><td style="text-align:left;"><code>succeeded</code></td><td style="text-align:left;"><code>COMPLETED</code></td><td style="text-align:left;">正常成功调用，账务与履约完全闭环</td></tr><tr><td style="text-align:left;"><code>released</code></td><td style="text-align:left;"><code>failed</code></td><td style="text-align:left;"><code>ROLLED_BACK</code></td><td style="text-align:left;">上游报错或超时，额度已 100% 自动解冻返还</td></tr><tr><td style="text-align:left;"><code>held</code></td><td style="text-align:left;"><code>failed</code></td><td style="text-align:left;"><code>ROLLBACK_PENDING</code></td><td style="text-align:left;">上游明确失败，调度器正在异步执行解冻释放</td></tr><tr><td style="text-align:left;"><code>unknown</code></td><td style="text-align:left;"><code>unknown</code></td><td style="text-align:left;"><code>RECONCILIATION_REQUIRED</code></td><td style="text-align:left;">网络与网关双向未知，由五重对账调度器核查平账</td></tr></tbody></table>',10))])}const _=d(p,[["render",A]]);export{u as __pageData,_ as default};
